    assert!(cmds.matches("tpad=stop").count() >= 2, "{cmds}");
    let d = v["probe"]["duration"].as_f64().unwrap();
    assert!((d - 1.4).abs() < 0.4, "freeze x2 ≈1.4s, got {d}; {v}");

    // dip at two scene cuts
